/** t() with {name} placeholders filled. */
export const tf = (lang, k, v = {}) => String(t(lang, k)).replace(/\{(\w+)\}/g, (_m, n) => (v[n] == null ? '' : String(v[n])));
/** The three sentinels call() answers with instead of throwing (CP-08). A reader that does not
 *  test a field of its own must ask this before it stores the answer, or a network blip is filed
 *  as the server's reply — which is how a registered customer was shown the sign-up form. */
export const transportFailed = (j) => !!(j && j.ok === false && String(j.error || '').startsWith('qd_'));
/** A string whose Arabic form carries {c} takes the counted noun from src/lib/countedNoun.ts,
 *  filled in by the caller: countPhrase(lang, n, 'line') → tf(lang, key, { n, c }). portalText
 *  imports nothing, because scripts/checks imports this file with bare node. */
export const EMIRATE_AR = { Dubai: 'دبي', 'Abu Dhabi': 'أبوظبي', Sharjah: 'الشارقة', Ajman: 'عجمان', 'Ras Al Khaimah': 'رأس الخيمة', 'Umm Al Quwain': 'أم القيوين', Fujairah: 'الفجيرة' };
export const emirateName = (e, lang) => (lang === 'ar' && EMIRATE_AR[e]) || e;

// A SERVER STRING IS NOT A SENTENCE IN THE CUSTOMER'S LANGUAGE. login_otp, kyc, customer_api and
// stripe_checkout answer in English, sometimes as a sentence and sometimes as a code
// ('stripe_not_configured' at HTTP 200), and the portal printed j.error verbatim. Codes and flags are
// matched first, then the fixed English sentences those functions send; anything unrecognised falls
// back to a localised generic line rather than to raw English or a snake_case code.
const CODE_KEY = {
  // login_otp verify answers role_conflict once the code proved the mailbox; role_guard no longer says so before (6 Oct 2026).
  role_conflict: 'conflict_supplier', role_conflict_phone: 'conflict_supplier_phone',
  stripe_not_configured: 'err_stripe_nc', stripe_error: 'err_stripe', intake_required: 'nr_more_details', registration_incomplete: 'err_registration',
  account_incomplete: 'err_registration', dob_required: 'err_dob_required', dob_invalid: 'err_dob_invalid', under_18: 'err_under_18',
  unauthorized: 'session_expired', 'Not signed in': 'session_expired', text_required: 'err_text_required', inquiry_closed: 'err_closed',
  not_your_inquiry: 'err_not_yours', 'Not your inquiry': 'err_not_yours', already_answered: 'err_already_answered', too_many_questions: 'err_rate',
  too_many_notes: 'err_rate', refund_window_elapsed: 'err_refund_window', not_found: 'err_not_found', forbidden: 'err_not_yours',
  // customer_api rate_supplier, 17 Sep 2026: a refused rating comes back as a 4xx with a code, never
  // as the 500 that used to carry a raw constraint name to the customer.
  review_comment_too_short: 'err_review_comment', rating_out_of_range: 'err_rating_range',
  // customer_api add_review_photos (T2): the photo refusals, in the customer's language.
  photo_not_image: 'err_photo_type', photo_too_large: 'err_photo_size', too_many_photos: 'err_photo_count', photo_save_failed: 'err_photo_fail', review_required: 'c_rate_group',
  // reveal_invoice, 21 Sep 2026: no invoice or receipt for a payment that has not settled.
  payment_not_settled: 'q_inv_not_paid',
  // call() answers with these three instead of throwing (CP-08, 22 Sep 2026): a request that timed
  // out, never left the browser, or came back as something other than JSON is a sentence the
  // customer can act on, not a blank screen or a raw parser error.
  resend_too_soon: 'err_resend_soon',
  qd_timeout: 'err_timeout', qd_network: 'err_network', qd_bad_response: 'err_generic',
};
const MSG_KEY = [
  [/do-not-send/i, 'err_suppressed'], [/create an account from a mobile/i, 'signup_email_only'], [/not linked|No account is registered/i, 'err_mobile_unknown'],
  [/more than one/i, 'err_ambiguous'], [/SMS sign-in is not enabled/i, 'err_sms_off'], [/SMS is not configured/i, 'err_sms_nc'], [/Too many/i, 'err_too_many'],
  [/expired/i, 'err_expired'], [/Incorrect|Enter the (6-digit )?code|code you received/i, 'err_incorrect'], [/valid email address or UAE/i, 'err_invalid_id'],
  [/valid mobile/i, 'err_phone'], [/enter your name/i, 'err_name'], [/suspended/i, 'err_suspended'], [/verify your email/i, 'err_email_verify'],
  [/many requests|many PDFs|short time/i, 'err_rate'], [/already rated/i, 'err_refund_rated'], [/completed with this supplier/i, 'err_refund_hired'],
  [/window has elapsed/i, 'err_refund_window'], [/not found/i, 'err_not_found'], [/No customer profile/i, 'load_failed'],
];
export function errText(j, lang, fallbackKey = 'err_generic') {
  if (!j) return t(lang, fallbackKey);
  if (j.ambiguous) return t(lang, 'err_ambiguous');
  if (j.suppressed) return t(lang, 'err_suppressed');
  for (const c of [j.code, j.error]) if (c && CODE_KEY[String(c)]) return t(lang, CODE_KEY[String(c)]);
  // A REFUSAL THAT ARRIVES IN BOTH LANGUAGES IS ALREADY THE SENTENCE (customer-portal audit CP-03 /
  // CP-10, 22 Sep 2026). customer_api, stripe_checkout, stripe_confirm and quote_compare now answer
  // a refusal with a machine `code`, a proper 4xx/5xx AND `message` / `message_ar`. A code with its
  // own key above keeps that wording; anything new is rendered in the customer's language rather
  // than falling through to the generic line.
  if (j.message && j.message_ar) return String(lang === 'ar' ? j.message_ar : j.message);
  const text = [j.error, j.message].filter(Boolean).join(' ');
  for (const [re, k] of MSG_KEY) if (re.test(text)) return t(lang, k);
  return t(lang, fallbackKey);
}

// ── ADDED 29 SEP 2026 (founder ledger 1018, item 2): the quote quality check in the comparison. quote_compare serves
// analysis.quality_check = { held, hours, notes: [{ label, label_ar, flags }] }; the flags are codes and numbers
// (scripts/sql/a_quote_is_checked_for_specs_prices_and_terms_before_the_customer_sees_it.sql, fn_quote_quality_flags),
// and the sentences are written here, in both languages.
Object.assign(T.en, {
  qq_title: 'Our quality check',
  qq_held: '{n} more quote(s) are held while the supplier corrects what our quality check found. Each appears here once it is corrected, or after {h} hours with the points shown beside it.',
  qq_uncorrected: 'not corrected by the supplier within {h} hours',
  qq_missing_spec: 'does not state: {specs}',
  qq_price_above: 'line {line} is {pct}% above the usual UAE price (AED {lo} to {hi} per {unit})',
  qq_price_below: 'line {line} is {pct}% below the usual UAE price (AED {lo} to {hi} per {unit}); check what it leaves out',
  qq_no_validity: 'no validity stated',
  qq_no_delivery_time: 'no delivery time stated',
  qq_no_vat_treatment: 'does not say whether VAT is included',
});
Object.assign(T.ar, {
  qq_title: 'فحص الجودة لدينا',
  qq_held: 'هناك {n} عرض/عروض أخرى معلّقة ريثما يصحّح المورّد ما وجده فحص الجودة لدينا. يظهر كل منها هنا فور تصحيحه، أو بعد {h} ساعة مع عرض الملاحظات بجانبه.',
  qq_uncorrected: 'لم يصحّحها المورّد خلال {h} ساعة',
  qq_missing_spec: 'لم يذكر: {specs}',
  qq_price_above: 'سعر البند {line} أعلى بنسبة {pct}% من السعر المعتاد في الإمارات (من {lo} إلى {hi} درهم لكل {unit})',
  qq_price_below: 'سعر البند {line} أقل بنسبة {pct}% من السعر المعتاد في الإمارات (من {lo} إلى {hi} درهم لكل {unit})، ويُستحسن التحقق مما لا يشمله',
  qq_no_validity: 'لم يذكر مدة صلاحية العرض',
  qq_no_delivery_time: 'لم يذكر مدة التسليم',
  qq_no_vat_treatment: 'لم يوضّح إن كان السعر شاملًا ضريبة القيمة المضافة',
});
/** One quality-check flag (quote_compare's quality_check.notes[].flags[]) as a phrase in the customer's language. */
export function qualityReason(f, lang) {
  const code = String((f && f.code) || '');
  const money = (x) => Number(x).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (code === 'missing_spec') return tf(lang, 'qq_missing_spec', { specs: (Array.isArray(f.specs) ? f.specs : []).map((s) => s && s.label).filter(Boolean).join(', ') });
  if (code === 'price_above' || code === 'price_below') return tf(lang, 'qq_' + code, { line: f.line_no, pct: Math.abs(Number(f.pct_vs_median) || 0), lo: money(f.p25), hi: money(f.p75), unit: f.unit });
  return T.en['qq_' + code] ? t(lang, 'qq_' + code) : '';
}
